func (t FlowNode) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t FlowNode) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "agent":
		return t.AsAgentNode()
	case "check_property":
		return t.AsCheckPropertyNode()
	case "create_cards":
		return t.AsCreateCardsNode()
	case "end":
		return t.AsEndNode()
	case "http_request":
		return t.AsHTTPRequestNode()
	case "human_review":
		return t.AsHumanReviewNode()
	case "join":
		return t.AsJoinNode()
	case "move_card":
		return t.AsMoveCardNode()
	case "set_property":
		return t.AsSetPropertyNode()
	case "split":
		return t.AsSplitNode()
	case "switch":
		return t.AsSwitchNode()
	case "transform":
		return t.AsTransformNode()
	case "trigger":
		return t.AsTriggerNode()
	case "wait_children":
		return t.AsWaitChildrenNode()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

